local mapIDs = {
    ["The Waking Shores"] = 2022, ["Ohn'ahran Plains"] = 2023,
    ["The Azure Span"] = 2024, ["Thaldraszus"] = 2025,
    ["Zaralek Cavern"] = 2133, ["The Forbidden Reach"] = 2151,
    ["Emerald Dream"] = 2200,
}
local function CopySpot(spot)
    local copy = {}
    for key, value in pairs(spot) do copy[key] = value end
    copy.isRoute = false
    copy.mapID = copy.mapID or mapIDs[copy.mapName]
    return copy
end

-- Resolve references against the original researched records before replacing
-- quality variants; this keeps the established species-specific farm anchors.
for _, record in ipairs(RECORDS) do
    local previous = Items[record.itemID]
    local source = record.reuseFrom and Items[record.reuseFrom]
        or (record.preserveExistingSpots and previous)
    for _, oldSpot in ipairs(source and source.spots or {}) do
        if not record.reuseSpotMatch or string.find(oldSpot.id or "", record.reuseSpotMatch, 1, true) then
            local spot = CopySpot(oldSpot)
            if record.reuseFrom then
                spot.id = oldSpot.id .. "-specialty-" .. record.itemID
                spot.tips = record.tips
                spot.sourceUrls = record.sourceUrls
                spot.routeType = record.acquisitionType or "material-search"
            end
            record.spots[#record.spots + 1] = spot
        end
    end
end
for _, record in ipairs(RECORDS) do
    Register(record)
end

-- Existing vendor-only Ohn'ahran Potato is omitted together with purchased
-- supplies in the new compositions. Its old vendor pins are not farm targets.
Items[197749] = nil

-- Copy shared legacy spots before setting flags so imported ore and herb
-- routes keep their original data and flags.
for _, item in pairs(Items) do
    if item.expansion == "dragonflight" and item.category ~= "Herb" and item.category ~= "Ore" then
        item.isRoute = false
        local spots = {}
        for _, spot in ipairs(item.spots or {}) do spots[#spots + 1] = CopySpot(spot) end
        item.spots = spots
    end
end
